        ctx.save_for_backward(input, weight)
        ctx.N, ctx.C_in, ctx.L_in = N, C_in, L_in
        ctx.C_out, ctx.K = C_out, K
        return output

    @staticmethod
    def backward(ctx, grad_output):
        # Simple fallback to PyTorch's autograd using the same operation.
        # This is not the most efficient but satisfies correctness.
        input, weight = ctx.saved_tensors
        # Use torch.nn.functional.conv1d for gradients (fp16)
        grad_input = torch.nn.grad.conv1d_input(
            input_shape=input.shape,
            grad_output=grad_output,
            weight=weight,
            stride=1,
            padding=0,
            dilation=1,
            groups=1
